pseudocode.ordinary:
before = Nia
seekRequest = seek(before, bay)
separationRequest = separate(before, 0, [before, parkedRobot], linearTuning)

weightedSeek = seekRequest * seekWeight
weightedSeparation = separationRequest * separationWeight
raw = weightedSeek + weightedSeparation
// Do not divide by the sum of the weights.

acceleration = blend([
  { acceleration: seekRequest, weight: seekWeight },
  { acceleration: separationRequest, weight: separationWeight }
], maxAcceleration)
// blend returns capLength(raw, maxAcceleration).

velocity = capLength(before.velocity + acceleration * dt, maxSpeed)
position = before.position + velocity * dt
Nia = before with position and velocity
// parkedRobot keeps its position; recompute requests next step.

pseudocode.rxjs:
// before$ supplies each fixed-step snapshot of Nia; movement is handled elsewhere.
requests$ = before$.pipe(
  // Each frame owns its two sources; concatMap keeps frames in order.
  concatMap(before => forkJoin({
    seekRequest: of(seek(before, bay)),
    separationRequest: of(separate(before, 0, [before, parkedRobot], linearTuning))
  })),
  // of emits once and completes; forkJoin needs both to emit and complete.
  map(({ seekRequest, separationRequest }) => {
    weightedSeek = seekRequest * seekWeight
    weightedSeparation = separationRequest * separationWeight
    raw = weightedSeek + weightedSeparation
    acceleration = capLength(raw, maxAcceleration)
    return { weightedSeek, weightedSeparation, raw, acceleration }
  })
)
// A non-completing source stalls its frame and queues later frames.
acceleration$ = requests$.pipe(map(({ acceleration }) => acceleration))
// Zero can mean silence or cancellation; keep requests$ to tell them apart.
// Clipping hides excess strength; this join cannot guarantee clearance or choose a detour.
